guidance.correct_example:
def find_user(a_username: str) -> Result[User]:
    cursor.execute('SELECT * FROM users WHERE username = ?', (a_username,))
    row = cursor.fetchone()
    if row is None:
        return Result.failure(f'User {a_username} not found')
    return Result.success(User.from_row(row))

guidance.incorrect_example:
def find_user(a_username: str) -> Result[User]:
    query = f'SELECT * FROM users WHERE username = \'{a_username}\''
    cursor.execute(query)
    return Result.success(User.from_row(cursor.fetchone()))
